/*
  Existing exports are retained for other pages that import
  ProjectMedia or ProjectCard from this file.
*/

export function ProjectMedia({
  project,
  className = '',
}: {
  project: Project
  className?: string
}) {
  const { tr } = useLang()
  const label = `${tr(project.name)} — ${tr(project.category)}`

  return project.image ? (
    <img
      src={project.image}
      alt={label}
      loading="lazy"
      decoding="async"
      className={`object-cover ${className}`}
    />
  ) : (
    <ProjectArt
      kind={project.art}
      label={label}
      className={className}
    />
  )
}

export function ProjectCard({
  project,
  index,
  wide = false,
}: {
  project: Project
  index: number
  wide?: boolean
}) {
  const { tr } = useLang()

  return (
    <article
      className={`work-card group relative overflow-hidden rounded-[1.75rem] border border-white/10 bg-navy-lift/25 transition-colors duration-500 hover:border-signal/70 ${
        wide
          ? 'grid h-full grid-cols-[1.35fr_1fr]'
          : 'flex flex-col'
      }`}
    >
      <div
        className={`relative overflow-hidden ${
          wide ? 'h-full' : 'aspect-[4/3]'
        }`}
      >
        <div className="work-art absolute -inset-x-[8%] inset-y-0">
          <ProjectMedia
            project={project}
            className="h-full w-full transition-transform duration-700 motion-safe:group-hover:scale-[1.06]"
          />
        </div>

        <span className="latin absolute start-5 top-5 text-xs font-medium text-white/70 tabular-nums">
          {String(index + 1).padStart(2, '0')}
        </span>

        {project.placeholder && (
          <span className="eyebrow absolute end-5 top-5 rounded-full border border-white/25 bg-navy/60 px-3 py-1.5 text-xs backdrop-blur-sm">
            {tr(ui.work.concept)}
          </span>
        )}
      </div>

      <div
        className={`flex flex-col ${
          wide
            ? 'justify-between gap-5 p-7 xl:p-10'
            : 'p-6 sm:p-8'
        }`}
      >
        <div>
          <p className="eyebrow text-signal">
            {tr(project.category)}
          </p>

          <h3 className="mt-3 text-3xl font-bold uppercase tracking-tight sm:text-4xl rtl:leading-snug rtl:tracking-normal">
            <Link
              to={`/work/${project.slug}`}
              className="after:absolute after:inset-0 after:content-[''] focus-visible:outline focus-visible:outline-2 focus-visible:outline-signal"
            >
              {tr(project.name)}
            </Link>
          </h3>

          <p className="muted mt-2 text-sm">
            {tr(project.industry)}
          </p>
        </div>

        <div className={wide ? '' : 'mt-6'}>
          <dl className="space-y-4 text-sm leading-relaxed">
            <div>
              <dt className="eyebrow mb-1 text-white/50">
                {tr(ui.work.challenge)}
              </dt>
              <dd className="text-white/85">
                {tr(project.challenge)}
