/* One complete image per project, without cropping. */
function PortfolioImage({
  project,
}: {
  project: PortfolioProject
}) {
  const { tr } = useLang()
  const [failed, setFailed] = useState(false)

  return (
    <div className="flex aspect-[4/3] items-center justify-center overflow-hidden rounded-2xl border border-white/10 bg-black/20">
      {failed ? (
        <div className="px-6 text-center">
          <p className="text-sm text-white/70">
            {tr({
              en: 'Project image unavailable',
              ar: 'صورة المشروع غير متوفرة',
            })}
          </p>
        </div>
      ) : (
        <img
          src={project.image}
          alt={`${tr(project.name)} — ${tr(project.description)}`}
          loading="lazy"
          decoding="async"
          onError={() => setFailed(true)}
          className="h-full w-full object-contain"
        />
      )}
    </div>
  )
}

export function Work() {
  const { tr, rtl } = useLang()
  const [activeId, setActiveId] = useState<string | null>(null)

  const sectionRef = useRef<HTMLElement>(null)
  const categoryHeadingRef = useRef<HTMLHeadingElement>(null)
  const categoryButtons = useRef<Record<string, HTMLButtonElement | null>>({})

  const activeCategory = workCategories.find(
    (category) => category.id === activeId,
  )

  const projectCount = (count: number) =>
    tr({
      en: `${count} projects`,
      ar: count === 2 ? 'مشروعان' : `${count} مشاريع`,
    })

  function openCategory(id: string) {
    setActiveId(id)

    requestAnimationFrame(() => {
      categoryHeadingRef.current?.focus({ preventScroll: true })
      sectionRef.current?.scrollIntoView({
        behavior: 'auto',
        block: 'start',
      })
    })
  }

  function backToCategories() {
    const previousId = activeId
    setActiveId(null)

    requestAnimationFrame(() => {
      if (previousId) {
        categoryButtons.current[previousId]?.focus({
          preventScroll: true,
        })
      }

      sectionRef.current?.scrollIntoView({
        behavior: 'auto',
        block: 'start',
      })
    })
  }

  return (
    <section
      ref={sectionRef}
      id="selected-work"
      dir={rtl ? 'rtl' : 'ltr'}
      aria-labelledby="selected-work-title"
      className="section relative scroll-mt-24 overflow-hidden"
    >
      <div
        aria-hidden="true"
        className="pointer-events-none absolute inset-x-0 top-0 h-px bg-gradient-to-r from-transparent via-white/15 to-transparent"
      />

      <div className="wrap relative">
        <header className="mb-12 sm:mb-16">
          <p className="eyebrow mb-6 text-signal">
            {tr({
              en: 'Selected work',
              ar: 'أعمال مختارة',
            })}
          </p>

          <h2
            id="selected-work-title"
            className="max-w-[15ch] text-[clamp(2.8rem,6.5vw,6.5rem)] font-light leading-[1.02] tracking-tight text-white rtl:max-w-none rtl:leading-tight rtl:tracking-normal"
          >
            {tr({
              en: 'A look inside',
              ar: 'نظرة داخل',
            })}

            <br />

            <span className="font-semibold">
              {tr({
                en: 'the studio',
                ar: 'الاستوديو',
              })}
              <span className="text-signal">.</span>
            </span>
          </h2>

          <p className="mt-6 text-base leading-relaxed text-white/60 sm:text-lg">
            {tr({
              en: 'Curated work across five disciplines.',
              ar: 'أعمال منتقاة عبر خمسة تخصصات.',
            })}
          </p>
        </header>

        {!activeCategory ? (
          <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
            {workCategories.map((category, index) => (
              <button
                key={category.id}
                ref={(element) => {
                  categoryButtons.current[category.id] = element
                }}
                type="button"
                onClick={() => openCategory(category.id)}
                aria-label={`${tr(category.title)} — ${projectCount(
                  category.projects.length,
                )}`}
                className="group relative flex min-h-[250px] flex-col items-start rounded-2xl border border-white/15 bg-white/[0.025] p-7 text-start transition-colors duration-300 hover:border-signal/60 hover:bg-white/[0.05] focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-signal sm:min-h-[280px] sm:p-9"
              >
                <span className="flex items-center gap-3 text-xs tracking-wide text-white/50">
                  <span className="latin tabular-nums">
                    {String(index + 1).padStart(2, '0')}
                  </span>

                  <span aria-hidden="true">·</span>

                  <span>
                    {projectCount(category.projects.length)}
                  </span>
                </span>

                <h3 className="mt-9 text-3xl font-medium leading-tight tracking-tight text-white sm:text-4xl rtl:tracking-normal">
                  {tr(category.title)}
                </h3>

                <span className="mt-auto flex w-full items-center justify-between gap-4 pt-10 text-sm font-medium text-white/75 transition-colors group-hover:text-signal">
                  <span>
                    {tr({
                      en: 'Explore',
                      ar: 'استكشف',
                    })}
                  </span>

                  <span
                    aria-hidden="true"
                    className="text-xl transition-transform duration-300 motion-safe:group-hover:translate-x-1 rtl:motion-safe:group-hover:-translate-x-1"
                  >
                    {rtl ? '←' : '→'}
                  </span>
                </span>
              </button>
            ))}
          </div>
        ) : (
          <div key={activeCategory.id}>
            <button
              type="button"
              onClick={backToCategories}
              className="mb-8 inline-flex items-center gap-3 rounded-sm py-2 text-sm text-white/65 transition-colors hover:text-signal focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-signal"
            >
              <span aria-hidden="true">
                {rtl ? '→' : '←'}
              </span>

              {tr({
                en: 'Back to categories',
                ar: 'العودة إلى التصنيفات',
              })}
            </button>

            <div className="mb-8 flex flex-wrap items-end justify-between gap-4 border-b border-white/10 pb-6">
              <h3
                ref={categoryHeadingRef}
                tabIndex={-1}
                className="text-3xl font-medium tracking-tight text-white outline-none sm:text-5xl rtl:tracking-normal"
              >
                {tr(activeCategory.title)}
              </h3>

              <p className="text-sm text-white/50">
                {projectCount(activeCategory.projects.length)}
              </p>
            </div>

            <div
              className={`grid items-start gap-x-6 gap-y-10 md:grid-cols-2 ${
                activeCategory.projects.length > 2
                  ? 'xl:grid-cols-3'
                  : ''
              }`}
            >
              {activeCategory.projects.map((project) => (
                <article key={project.id} className="min-w-0">
                  <PortfolioImage project={project} />

                  <div className="px-1 pt-5">
                    <h4 className="text-xl font-medium leading-snug text-white sm:text-2xl">
                      {tr(project.name)}
                    </h4>

                    <p className="mt-2 text-sm leading-relaxed text-white/55">
                      {tr(project.description)}
                    </p>
                  </div>
                </article>
              ))}
            </div>
          </div>
        )}
      </div>
    </section>
  )
}
